#!/usr/bin/env python3
import csv,json,hashlib
from pathlib import Path
ROOT=Path('/output'); D=ROOT/'derived'; M=ROOT/'models'
rows=list(csv.DictReader(open(D/'author_sanitized.csv')))
with open(D/'analysis_panel.csv','w',newline='') as f:
    fs=['city','population_density_2019','cases_2020_03_27','cases_2020_04_07','independent_pm10_exposure_status']
    w=csv.DictWriter(f,fieldnames=fs); w.writeheader()
    for r in rows:w.writerow({'city':r['Italian Province Capital'].strip(),'population_density_2019':r['Density h/km2'],'cases_2020_03_27':r['Infected 27.March, 2020'],'cases_2020_04_07':r['Infected 7.April 2020'],'independent_pm10_exposure_status':'not_available: EEA linked PM10 historical object HTTP 404'})
M.joinpath('model_output.txt').write_text('NO MODEL FIT\nBlocked before modelling: 0/55 observations have independently constructed 2018 exposure. OLS was not executed.\n')
def sha(p): return hashlib.sha256(Path(p).read_bytes()).hexdigest()
sources=[{'role':'article','url':'https://www.ebi.ac.uk/europepmc/webservices/rest/PMC7781409/fullTextXML','retrieved':True,'sha256':sha('/study/article.xml')},{'role':'author_designated_outcome_and_covariate_table_sanitized','url':'https://data.mendeley.com/datasets/bbnyhp6gfh/1','retrieved':True,'sha256':sha('/output/raw/author_table.xlsx')},{'role':'independent_exposure_station_catalogue','url':'https://air.discomap.eea.europa.eu/arcgis/rest/services/AirQuality/AirQualityDownloadServiceEUMonitoringStations/MapServer/0','retrieved':True,'sha256':sha('/output/raw/eea_italy_stations.geojson')},{'role':'independent_exposure_historical_series_attempt','url':'https://eeadmz1batchservice02.blob.core.windows.net/airquality-p-e1a/IT/SPO.IT1846A_5_BETA_2006-04-30_00_00_00.parquet','retrieved':False,'sha256':None},{'role':'geographic_assignment','url':'https://nominatim.openstreetmap.org/search','retrieved':True,'sha256':sha('/output/raw/geocode_01.json')}]
json.dump(sources,open(ROOT/'source_manifest.json','w'),indent=2)
fidelity={'study_id':'33398753','record_type':'record_reanalysis_fidelity','fidelity_status':'blocked_before_fit','published_model':'log-log OLS cases on pollution and population density','reanalysis_model':'predeclared but not fitted','departures':['PM10-only independent exposure substituted for PM10-or-ozone composite','author table sanitized to remove pollution before use']}
json.dump(fidelity,open(ROOT/'fidelity_record.json','w'),indent=2)
result={'study_id':'33398753','status':'completed_blocker','target':{'outcome':'Confirmed COVID-19 infected individuals, city, 7 April 2020','pollutant':'2018 days exceeding PM10 or ozone limits','geography':'55 Italian provincial capitals','period':'2018 exposure; March-April 2020 outcomes','effect_scale':'log-log OLS elasticity and transformed outcome ratio per 1% exposure increase'},'sources':sources,'substitutions':[{'dimension':'exposure','published':'PM10-or-ozone exceedance days','reanalysis':'EEA PM10 daily means >50 ug/m3','reason':'Independent source required; unavailable after terminal 404.'},{'dimension':'outcome','published':'Ministero della Salute city counts','reanalysis':'Sanitized author-designated Mendeley table','reason':'Public deposited table; pollution field dropped before inspection.'}],'coverage':{'eligible_units':55,'included_units':0,'eligible_times':2,'included_times':0,'notes':'EEA historical series retrieval failed at the first deterministic station assignment; no model fit.'},'effect':None,'artifacts':{'code':'/output/code/run_analysis.py','source_manifest':'/output/source_manifest.json','exposure':'/output/derived/eea_pm10_exposure.csv','analysis_panel':'/output/derived/analysis_panel.csv','model_output':'/output/models/model_output.txt','decision_log':'/output/decision_log.md','fidelity_record':'/output/fidelity_record.json'},'blockers':['EEA advertised historical PM10 object returned terminal HTTP 404.','Independent exposure coverage is 0/55; model fitting would violate the contract.']}
json.dump(result,open(ROOT/'result.json','w'),indent=2)
print(json.dumps({'study_id':'33398753','status':'completed_blocker','eligible_units':55,'included_units':0,'model_fit':False}))
